import React, { useRef, useEffect, useState } from 'react';
import Button from '../atoms/Button';
import { StatusDot } from '../atoms/StatusDot';
import { useLiveDataStore, PssEventData } from '../../stores/liveDataStore';
import { useAppStore } from '../../stores/index';
import { usePssMatchStore } from '../../stores/pssMatchStore';
import { useI18n } from '../../i18n/index';

const colorOptions = [
  { color: 'red', class: 'bg-red-500' },
  { color: 'blue', class: 'bg-blue-500' },
  { color: 'yellow', class: 'bg-yellow-400' },
];

// Event type filter buttons (order: K, P, H, TH, TB, R)
const eventTypeOptions = [
  { label: 'KICK', value: 'K' },
  { label: 'PUNCH', value: 'P' },
  { label: 'HEAD', value: 'H' },
  { label: 'TECH HEAD', value: 'TH' },
  { label: 'TECH BODY', value: 'TB' },
  { label: 'REFEREE', value: 'R' },
];

const EventTableSection: React.FC = () => {
  const tableRef = useRef<HTMLDivElement>(null);
  const selectRef = useRef<HTMLSelectElement>(null);
  const [selectWidthPx, setSelectWidthPx] = useState<number | null>(null);
  const [selectedIdx, setSelectedIdx] = useState<number | null>(null);
  const [colorFilter, setColorFilter] = useState<string | null>(null);
  const [eventTypeFilter, setEventTypeFilter] = useState<string | null>(null);
  
  // Get real-time data from stores
  const { 
    events, 
    currentRound, 
    currentRoundTime, 
    isConnected, 
    getFilteredEvents
  } = useLiveDataStore();
  
  const { isManualModeEnabled } = useAppStore();
  const matchNumber = usePssMatchStore((s) => s.matchData.matchConfig?.number);
  const isLoaded = usePssMatchStore((s) => s.matchData.isLoaded);
  const isReviewMode = usePssMatchStore((s) => s.matchData.isReviewMode);
  // Recent matches list by DB id for review dropdown
  const recentMatchesRef = useRef<Array<{ id: number; label: string }>>([]);
  // Load events for review mode
  const [reviewMatchId, setReviewMatchId] = useState<string | null>(null);
  const setEvents = useLiveDataStore.getState().setEvents;
  useEffect(() => {
    (async () => {
      try {
        const { invoke } = await import('@tauri-apps/api/core');
        const resp: any[] = await invoke('pss_list_recent_matches', { limit: 20 });
        recentMatchesRef.current = (resp || [])
          .filter((m: any) => m && m.id != null)
          .map((m: any) => {
            const num = m.match_number ?? '';
            const catRaw = m.category ?? '';
            const cat = (() => {
              let s = String(catRaw);
              s = s.replace(/round of\s*128/i, 'R128');
              s = s.replace(/round of\s*64/i, 'R64');
              s = s.replace(/round of\s*32/i, 'R32');
              s = s.replace(/round of\s*16/i, 'R16');
              s = s.replace(/bronze\s*medal\s*contest/i, 'BMD');
              s = s.replace(/semifinals?/i, 'SF');
              s = s.replace(/qu(?:a|)rterfinals?/i, 'QF');
              s = s.replace(/finals?/i, 'F');
              return s;
            })();
            const whenIso = m.updated_at || m.created_at;
            const whenMs = m.updated != null ? (m.updated as number) * 1000
              : m.created != null ? (m.created as number) * 1000
              : whenIso ? new Date(whenIso).getTime() : 0;
            const dt = m.updated != null
              ? new Date((m.updated as number) * 1000).toLocaleString(undefined, {
                  year: 'numeric',
                  month: '2-digit',
                  day: '2-digit',
                  hour: '2-digit',
                  minute: '2-digit',
                })
              : m.created != null
              ? new Date((m.created as number) * 1000).toLocaleString(undefined, {
                  year: 'numeric',
                  month: '2-digit',
                  day: '2-digit',
                  hour: '2-digit',
                  minute: '2-digit',
                })
              : whenIso
              ? new Date(whenIso).toLocaleString(undefined, {
                  year: 'numeric',
                  month: '2-digit',
                  day: '2-digit',
                  hour: '2-digit',
                  minute: '2-digit',
                })
              : '';
            const base = `#${num} ${cat}`.trim();
            const label = dt ? `${base} • ${dt}` : base;
            return { id: Number(m.id), label, sortKey: whenMs };
          })
          .sort((a: any, b: any) => b.sortKey - a.sortKey)
          .map((x: any) => ({ id: x.id, label: x.label }))
          .slice(0, 20);
      } catch (_) {
        recentMatchesRef.current = [];
      }
    })();
  }, [matchNumber]);

  // Lock the dropdown width to its initial rendered width so adding date/time
  // does not change its size. We apply a dynamic CSS rule to avoid inline styles.
  useEffect(() => {
    if (selectRef.current && selectWidthPx == null) {
      setSelectWidthPx(selectRef.current.offsetWidth);
    }
  }, [selectWidthPx]);

  useEffect(() => {
    if (selectWidthPx != null) {
      const styleId = 'pss-select-width-style';
      let tag = document.getElementById(styleId) as HTMLStyleElement | null;
      const width = Math.max(0, Math.floor(selectWidthPx * 2));
      const css = `.pss-fixed-select-width{width:${width}px !important;}`;
      if (!tag) {
        tag = document.createElement('style');
        tag.id = styleId;
        tag.type = 'text/css';
        tag.appendChild(document.createTextNode(css));
        document.head.appendChild(tag);
      } else {
        tag.textContent = css;
      }
    }
  }, [selectWidthPx]);

  const loadMatchEventsForReview = async (idStr: string) => {
    try {
      const { invoke } = await import('@tauri-apps/api/core');
      // Normalize id to numeric-only for robust backend resolution
      const numericId = idStr.replace(/[^0-9]/g, '');
      const effective = numericId.length > 0 ? numericId : idStr;
      let resp: any = await invoke('pss_get_events_for_match', { matchId: effective });
      // Expect resp to be array of events matching PssEventData shape or convertible
      let list = Array.isArray(resp) ? resp : [];
      // Convert to PssEventData[] if needed
      const normalized = list.map((e: any) => ({
        id: String(e.id ?? `${idStr}_${Math.random()}`),
        eventType: e.type ?? e.event_type ?? '',
        eventCode: e.event_code ?? '',
        athlete: (e.athlete ?? 'yellow') as any,
        round: Number(e.round ?? 1),
        time: String(e.time ?? '0:00'),
        timestamp: String(e.timestamp ?? new Date().toISOString()),
        rawData: String(e.raw_data ?? ''),
        description: String(e.description ?? ''),
      }));
      // If empty via match number, resolve DB id via details and retry with DB id
      if (normalized.length === 0) {
        try {
          const details: any = await invoke('pss_get_match_details', { matchId: effective });
          const dbId = details?.match?.id;
          if (dbId != null) {
            resp = await invoke('pss_get_events_for_match', { matchId: String(dbId) });
            list = Array.isArray(resp) ? resp : [];
            const normalized2 = list.map((e: any) => ({
              id: String(e.id ?? `${dbId}_${Math.random()}`),
              eventType: e.type ?? e.event_type ?? '',
              eventCode: e.event_code ?? '',
              athlete: (e.athlete ?? 'yellow') as any,
              round: Number(e.round ?? 1),
              time: String(e.time ?? '0:00'),
              timestamp: String(e.timestamp ?? new Date().toISOString()),
              rawData: String(e.raw_data ?? ''),
              description: String(e.description ?? ''),
            }));
            setEvents(normalized2.reverse());
            setReviewMatchId(String(dbId));
          } else {
            setEvents([]);
            setReviewMatchId(effective);
          }
        } catch (e) {
          // If details fail, keep empty
          setEvents([]);
          setReviewMatchId(effective);
        }
      } else {
        setEvents(normalized.reverse());
        setReviewMatchId(effective);
      }

      // Also load match details to populate MatchDetailsSection
      try {
        const details: any = await invoke('pss_get_match_details', { matchId: effective });
        if (details && details.athlete1 && details.athlete2) {
          const a1 = {
            short: details.athlete1.short_name ?? '',
            long: details.athlete1.long_name ?? '',
            country: details.athlete1.country_code ?? '',
            iocCode: details.athlete1.country_code ?? '',
          } as any;
          const a2 = {
            short: details.athlete2.short_name ?? '',
            long: details.athlete2.long_name ?? '',
            country: details.athlete2.country_code ?? '',
            iocCode: details.athlete2.country_code ?? '',
          } as any;
          const { usePssMatchStore } = await import('../../stores/pssMatchStore');
          usePssMatchStore.getState().updateAthletes(a1, a2);
          if (details.match) {
            const cfg = {
              number: Number(details.match.number ?? 0),
              category: String(details.match.category ?? ''),
              weight: String(details.match.weight ?? ''),
              division: String(details.match.division ?? ''),
              totalRounds: 3,
              roundDuration: 120,
              countdownType: 'cntDown',
              format: 5,
            } as any;
            usePssMatchStore.getState().updateMatchConfig(cfg);
          }
          // Enter review mode explicitly; do not mark as live-loaded
          usePssMatchStore.getState().setReviewMode(true);
          usePssMatchStore.getState().setMatchLoaded(false);
        }
      } catch (e) {
        console.warn('⚠️ Failed to load match details for review:', e);
      }
    } catch (err) {
      console.warn('⚠️ Failed to load match events for review:', err);
      // Fall back to recent events API if specific command is unavailable
      try {
        const { invoke } = await import('@tauri-apps/api/core');
        const resp2: any = await invoke('pss_get_events');
        const normalized = (Array.isArray(resp2) ? resp2 : []).map((e: any) => ({
          id: String(e.id ?? `${idStr}_${Math.random()}`),
          eventType: e.type ?? e.event_type ?? '',
          eventCode: e.event_code ?? '',
          athlete: (e.athlete ?? 'yellow') as any,
          round: Number(e.round ?? 1),
          time: String(e.time ?? '0:00'),
          timestamp: String(e.timestamp ?? new Date().toISOString()),
          rawData: String(e.raw_data ?? ''),
          description: String(e.description ?? ''),
        }));
        setEvents(normalized.reverse());
        setReviewMatchId(idStr);
      } catch (_) {
        // ignore
      }
    }
  };

  // Filtering logic - only show important events when manual mode is OFF
  const allEvents = isManualModeEnabled ? [] : getFilteredEvents(colorFilter, eventTypeFilter);
  
  // Filter to only show important events for the event table
  const filteredEvents = allEvents.filter(event => {
    // Only show events with specific event codes that are important for the table
    const importantEventCodes = ['K', 'P', 'H', 'TH', 'TB', 'R'];
    const isImportant = importantEventCodes.includes(event.eventCode);
    
    return isImportant;
  });



  // Auto-scroll to top when new events arrive (since newest are now at top)
  useEffect(() => {
    if (tableRef.current) {
      tableRef.current.scrollTop = 0;
    }
  }, [events]);

  const handleScrollTopAndClear = () => {
    if (tableRef.current) {
      tableRef.current.scrollTop = tableRef.current.scrollHeight;
    }
    setColorFilter(null);
    setEventTypeFilter(null);
  };

  // Format time for display (convert from "m:ss" to "mm.ss.000" format)
  const formatTimeForDisplay = (time: string): string => {
    // Use the event's time (which is the current store time when event was created)
    const displayTime = time;
    
    if (!displayTime || displayTime === '0:00') return '00.00.000';
    
    const parts = displayTime.split(':');
    if (parts.length === 2) {
      const minutes = parts[0].padStart(2, '0');
      const seconds = parts[1].padStart(2, '0');
      return `${minutes}.${seconds}.000`;
    }
    
    return displayTime;
  };

  // Get athlete color for display
  const getAthleteColor = (athlete: string): string => {
    switch (athlete) {
      case 'blue': return 'bg-blue-500';
      case 'red': return 'bg-red-500';
      case 'yellow': return 'bg-yellow-400';
      default: return 'bg-gray-500';
    }
  };

  const { t } = useI18n();
  return (
    <div className="flex flex-col space-y-4 overflow-hidden pt-4">
      {/* Section Title */}
      <div className="flex-shrink-0 flex items-center justify-between">
        <div className="text-lg font-semibold text-gray-200 flex items-center gap-2" />
        <div className="flex items-center space-x-2">
          {isManualModeEnabled && (
            <span className="text-xs text-yellow-400 bg-yellow-900/20 px-2 py-1 rounded">
              {t('live.manual_mode', 'Manual Mode')}
            </span>
          )}
        </div>
      </div>
      
      {/* Centered wrapper for Event Table and Filter Stack */}
      <div className="flex justify-center flex-1 min-h-0 overflow-hidden">
        <div className="flex flex-row items-start">
          {/* Event Table (left) */}
          <div className="w-80 flex flex-col overflow-hidden mr-3">
            {/* Table Header */}
            <div className="flex-shrink-0 flex text-xs text-gray-400 mb-3 border-b border-gray-600 pb-2 items-center mt-2">
              <div className="w-16 font-semibold text-white px-1 rounded mr-2 ml-12">{t('table.rnd', 'RND')}</div>
              <div className="w-24 font-semibold mr-2 ml-1">{t('common.time', 'TIME').toUpperCase()}</div>
              <div className="w-32 font-semibold flex items-center space-x-1 -ml-8">
                <span>{t('common.event', 'EVENT').toUpperCase()}</span>
                {colorOptions.map((opt) => (
                  <button
                    key={opt.color}
                    className={`
                      ${colorFilter === opt.color ? 'ring-2 ring-white rounded-full' : 'rounded-full'}
                      transition-all duration-200 cursor-pointer p-0.5 w-5 h-5 flex items-center justify-center
                    `}
                    onClick={() => setColorFilter(colorFilter === opt.color ? null : opt.color)}
                    title={
                      opt.color === 'red'
                        ? t('live.color.red', 'Red')
                        : opt.color === 'blue'
                        ? t('live.color.blue', 'Blue')
                        : t('live.color.yellow', 'Yellow')
                    }
                    type="button"
                  >
                    <StatusDot color={opt.class} size="w-3 h-3" />
                  </button>
                ))}
              </div>
            </div>
            
            {/* Event Rows */}
            <div ref={tableRef} className="h-64 space-y-1 overflow-y-auto bg-[#1a2a3a] rounded-md p-3">
              {isManualModeEnabled ? (
                <div className="flex items-center justify-center h-full text-gray-500 text-sm">
                  {t('live.manual_active', 'Manual Mode Active - Real-time events disabled')}
                </div>
              ) : filteredEvents.length === 0 ? (
                <div className="flex items-center justify-center h-full text-gray-500 text-sm">
                  {isConnected ? t('live.waiting', 'Waiting for events...') : t('live.not_connected_pss', 'Not connected to PSS')}
                </div>
              ) : (
                filteredEvents.map((event, idx) => (
                  <div
                    key={event.id}
                    className={`flex text-sm cursor-pointer transition-colors duration-150 rounded px-2 py-2 ${
                      selectedIdx === idx ? 'bg-blue-900/60 border border-blue-400' : 'hover:bg-gray-700/50'
                    }`}
                    onClick={() => setSelectedIdx(idx)}
                    onDoubleClick={async () => {
                      // Only allow playback in review mode to guarantee DB-backed event ids
                      if (!isReviewMode) return;
                      try {
                        const { invoke } = await import('@tauri-apps/api/core');
                        const numeric = String(event.id).replace(/[^0-9]/g, '');
                        const eventId = numeric.length > 0 ? Number(numeric) : Number(event.id);
                        if (!Number.isFinite(eventId)) return;
                        await invoke('ivr_open_event_video', { eventId });
                      } catch (e) {
                        console.warn('Failed to open event video:', e);
                      }
                    }}
                  >
                            <div className="w-16 text-gray-300 font-bold mr-2 ml-8">
          R{event.round}
        </div>
        <div className="w-24 text-gray-300 mr-2">
          {formatTimeForDisplay(event.time)}
        </div>
                    <div className="w-32 flex items-center space-x-2 pl-10">
                      <StatusDot color={getAthleteColor(event.athlete)} size="w-4 h-4" />
                      <span className="text-white font-medium">{event.eventCode}</span>
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>
          
          {/* Filter Stack (right) */}
          <div className="relative w-16 flex-shrink-0 h-64 pt-2">
            {/* Clear Filter Button (Up Arrow) - positioned at top */}
            <Button
              variant="secondary"
              size="sm"
              onClick={handleScrollTopAndClear}
              title={t('live.clear_and_scroll', 'Scroll to bottom (oldest events) and clear filters')}
              className="absolute top-0 w-8 h-8 p-0 flex items-center justify-center text-base"
            >
              ↑
            </Button>
            

            
            {/* Event Type Filter Buttons - positioned to align with table bottom */}
            <div className="absolute bottom-0 flex flex-col space-y-2 translate-y-[50px]">
              {eventTypeOptions.map(type => (
                <Button
                  key={type.value}
                  variant={eventTypeFilter === type.value ? 'primary' : 'secondary'}
                  size="sm"
                  onClick={() => setEventTypeFilter(eventTypeFilter === type.value ? null : type.value)}
                  title={
                    type.value === 'K'
                      ? t('live.event_type.kick', 'Kick')
                      : type.value === 'P'
                      ? t('live.event_type.punch', 'Punch')
                      : type.value === 'H'
                      ? t('live.event_type.head', 'Head')
                      : type.value === 'TH'
                      ? t('live.event_type.tech_head', 'Tech Head')
                      : type.value === 'TB'
                      ? t('live.event_type.tech_body', 'Tech Body')
                      : t('live.event_type.referee', 'Referee')
                  }
                  className="w-8 h-8 p-0 text-xs font-bold"
                  disabled={isManualModeEnabled}
                >
                  {type.value}
                </Button>
              ))}
            </div>
          </div>
        </div>
      </div>
      
      {/* Current Status Bar */}
      <div className="flex-shrink-0 flex items-center justify-between text-xs text-gray-400 border-t border-gray-600 pt-2">
        <div className="flex items-center space-x-4">
          <span>{t('live.round_label', 'Round')}: {currentRound}</span>
          <span>{t('live.time_label', 'Time')}: {currentRoundTime}</span>
        </div>
        <div className="flex items-center space-x-2">
          <span>{t('live.total_label', 'Total')}: {events.length}</span>
          <span>{t('live.table_label', 'Table')}: {filteredEvents.length}</span>
        </div>
      </div>
    </div>
  );
};

export default EventTableSection; 